
(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const DB = () => window.db || (typeof db !== 'undefined' ? db : null);
  const USER = () => window.currentUser || (typeof currentUser !== 'undefined' ? currentUser : null);
  const CHATS = () => (typeof conversations !== 'undefined' ? conversations : (window.conversations || []));
  const esc = v => String(v ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
  const say = m => (window.toast || window.notify || window.notifyMsg || console.info)(String(m ?? 'Неизвестная ошибка'));
  const errText = e => e?.message || e?.error_description || String(e || 'Неизвестная ошибка');
  const when = v => v ? new Date(v).toLocaleString('ru-RU') : '—';
  const publishableKey = typeof SUPABASE_KEY !== 'undefined' ? SUPABASE_KEY : '';
  const supabaseUrl = typeof SUPABASE_URL !== 'undefined' ? SUPABASE_URL : 'https://xxvcsaomkyknudoaixbs.supabase.co';
// -------------------- Group settings and membership --------------------
  if(window.__RIM_GROUP_SETTINGS_OWNED){/* modular owns group settings */}else window.rimOpenGroupSettings=async id=>{
    const d=DB(),u=USER(),chat=CHATS().find(x=>x.id===id);if(!d||!u||!chat||chat.type!=='group')return say('Группа не найдена.');
    const [{data:g,error:ge},{data:members,error:me}]=await Promise.all([d.from('conversations').select('*').eq('id',id).single(),d.from('conversation_members').select('user_id,role,joined_at').eq('conversation_id',id).order('joined_at')]);if(ge)return say(errText(ge));if(me)return say(errText(me));
    const ids=(members||[]).map(x=>x.user_id),{data:profiles,error:pe}=ids.length?await d.from('profiles').select('id,username,display_name').in('id',ids):{data:[],error:null};if(pe)return say(errText(pe));const pm=Object.fromEntries((profiles||[]).map(p=>[p.id,p]));
    const own=members.find(x=>x.user_id===u.id),manager=g.created_by===u.id||['owner','admin'].includes(own?.role);if(!manager)return say('Настройки доступны владельцу и администраторам группы.');
    window.showModal(`<div style="max-height:78vh;overflow:auto"><h2 class="modal-title">Настройки группы</h2><label>Название</label><input id="rimGroupTitle" class="field" maxlength="100" value="${esc(g.title||'')}"/><label>Описание</label><textarea id="rimGroupDesc" class="field" rows="3" maxlength="1000">${esc(g.description||'')}</textarea><label class="settings-row"><span>Закрытая группа</span><input id="rimGroupPrivate" type="checkbox" ${g.is_private!==false?'checked':''}></label><div class="row" style="flex-wrap:wrap"><button class="primary-btn" onclick="rimSaveGroupSettings('${id}')">Сохранить</button><button class="action-btn" onclick="rimPickGroupAvatar('${id}')">Аватар</button><input id="rimGroupAvatarFile" type="file" accept="image/jpeg,image/png,image/webp" hidden onchange="rimUploadGroupAvatar('${id}')"></div><div class="row" style="flex-wrap:wrap;margin:10px 0"><button class="action-btn" onclick="rimGroupMakeInvite('${id}')">Создать ссылку-приглашение</button>${g.invite_code?`<button class="action-btn" onclick="rimCopyGroupInvite('${g.invite_code}')">Копировать код</button><button class="action-btn danger-btn" onclick="rimGroupRevokeInvite('${id}')">Отозвать ссылку</button>`:''}</div><div class="rim-update-muted">${g.invite_code?'Код приглашения: '+esc(g.invite_code):'Ссылка приглашения пока не создана.'}</div><h3>Добавить участника</h3><div class="rim-search-panel"><input id="rimGroupAddUsername" class="field" placeholder="@username"><button class="action-btn" onclick="rimGroupAddMember('${id}')">Добавить</button></div><h3>Участники · ${members.length}</h3>${members.map(m=>`<div class="rim-group-member"><div><b>${esc(pm[m.user_id]?.display_name||pm[m.user_id]?.username||'Участник')}</b><div class="rim-update-muted">@${esc(pm[m.user_id]?.username||'—')} · ${esc(m.role)}</div></div>${m.role==='owner'?'':`<div class="row"><select class="field" id="rimGroupRole-${m.user_id}"><option value="member" ${m.role==='member'?'selected':''}>Участник</option><option value="admin" ${m.role==='admin'?'selected':''}>Администратор</option></select><button class="action-btn" onclick="rimGroupSetRole('${id}','${m.user_id}')">Роль</button><button class="action-btn danger-btn" onclick="rimGroupRemoveMember('${id}','${m.user_id}')">Удалить</button></div>`}</div>`).join('')}${g.created_by===u.id?`<button class="action-btn" style="width:100%;margin-top:10px" onclick="rimGroupTransferOwner('${id}')">Передать владение</button>`:''}<button class="action-btn danger-btn" style="width:100%;margin-top:8px" onclick="rimGroupLeave('${id}')">Покинуть группу</button></div>`);
  };
  window.rimSaveGroupSettings=async id=>{const d=DB(),title=$('rimGroupTitle')?.value.trim(),description=$('rimGroupDesc')?.value||'',isPrivate=$('rimGroupPrivate')?.checked!==false;if(!title)return say('Название обязательно.');const {data,error}=await d.rpc('rim_group_update_settings',{p_conversation_id:id,p_title:title,p_description:description,p_is_private:isPrivate,p_avatar_path:null});if(error)return say(errText(error));const chat=CHATS().find(x=>x.id===id);if(chat)Object.assign(chat,data);say('Настройки группы сохранены.');window.closeModal?.();await window.openConversation(id);};
  window.rimGroupAddMember=async id=>{const username=$('rimGroupAddUsername')?.value.trim();if(!username)return say('Введите @username.');const {error}=await DB().rpc('rim_group_add_member',{p_conversation_id:id,p_username:username});if(error)return say(errText(error));say('Участник добавлен.');await window.rimOpenGroupSettings(id);};
  window.rimGroupRemoveMember=async(id,userId)=>{if(!confirm('Удалить участника из группы?'))return;const {error}=await DB().rpc('rim_group_remove_member',{p_conversation_id:id,p_user_id:userId});if(error)return say(errText(error));await window.rimOpenGroupSettings(id);};
  window.rimGroupSetRole=async(id,userId)=>{const role=$('rimGroupRole-'+userId)?.value;const {error}=await DB().rpc('rim_group_set_member_role',{p_conversation_id:id,p_user_id:userId,p_role:role});if(error)return say(errText(error));await window.rimOpenGroupSettings(id);};
  window.rimGroupLeave=async id=>{if(!confirm('Покинуть группу?'))return;const {error}=await DB().rpc('rim_group_leave',{p_conversation_id:id});if(error)return say(errText(error));window.closeModal?.();await window.loadConversations?.();window.backToChats?.();};
  window.rimPickGroupAvatar=id=>$('rimGroupAvatarFile')?.click();
  window.rimUploadGroupAvatar=async id=>{const d=DB(),u=USER(),file=$('rimGroupAvatarFile')?.files?.[0];if(!file)return;if(file.size>3*1024*1024)return say('Аватар должен быть не больше 3 МБ.');const path=u.id+'/groups/'+id+'/'+crypto.randomUUID()+'.'+(file.name.split('.').pop()||'jpg');const {error:up}=await d.storage.from('avatars').upload(path,file,{contentType:file.type||'image/jpeg',upsert:false});if(up)return say(errText(up));const g=await d.from('conversations').select('title,description,is_private').eq('id',id).single();if(g.error)return say(errText(g.error));const {error}=await d.rpc('rim_group_update_settings',{p_conversation_id:id,p_title:g.data.title||'Группа',p_description:g.data.description||'',p_is_private:g.data.is_private,p_avatar_path:path});if(error)return say(errText(error));const chat=CHATS().find(x=>x.id===id);if(chat)chat.avatar_path=path;await window.rimOpenGroupSettings(id);};

  window.rimGroupMakeInvite=async id=>{const {data,error}=await DB().rpc('rim_group_create_invite',{p_conversation_id:id});if(error)return say(errText(error));try{await navigator.clipboard.writeText(data);}catch(_){}say('Код приглашения создан: '+data);await window.rimOpenGroupSettings(id);};
  window.rimCopyGroupInvite=async code=>{try{await navigator.clipboard.writeText(code);say('Код приглашения скопирован.');}catch(_){say('Код: '+code);}};
  window.rimGroupRevokeInvite=async id=>{if(!confirm('Отозвать ссылку приглашения?'))return;const {error}=await DB().rpc('rim_group_revoke_invite',{p_conversation_id:id});if(error)return say(errText(error));await window.rimOpenGroupSettings(id);};
  window.rimGroupTransferOwner=async id=>{const username=prompt('Username нового владельца (он должен быть участником группы):');if(!username)return;const {data:p,error:pe}=await DB().from('profiles').select('id,username').eq('username',username.replace(/^@/,'' )).maybeSingle();if(pe||!p)return say('Пользователь не найден.');if(!confirm('Передать владение группе пользователю @'+p.username+'? Это действие нельзя отменить автоматически.'))return;const {error}=await DB().rpc('rim_group_transfer_owner',{p_conversation_id:id,p_new_owner_id:p.id});if(error)return say(errText(error));say('Владение передано.');window.closeModal?.();await window.openConversation(id);};
  window.rimJoinGroupByInvite=async()=>{const code=prompt('Вставьте код приглашения в группу:');if(!code)return;const {data,error}=await DB().rpc('rim_group_join_invite',{p_code:code.trim()});if(error)return say(errText(error));say('Вы вступили в группу.');await window.loadConversations?.();await window.openConversation(data);};
})();

